import { sculptureLayout, storyProgress } from './editorial-core.mjs';
import { sceneFrame } from './motion-core.mjs';

export function mountEditorialHero(){
  const root=document.querySelector('#cinematic');root.className='editorial-hero';
  root.innerHTML=`<div class="editorial-pin"><div class="editorial-layout shell"><div class="editorial-copy"><section class="editorial-copy-block" data-copy="0"><span class="editorial-kicker">LOCAL AI. A MORE CONNECTED WAY TO WORK.</span><h1 id="hero-heading">Design it.<br>Build it.<br><em>Keep context.</em></h1><p>A workspace for the decisions, designs, and code behind your next project. Grounded on your machine.</p><div class="scene-actions"><button class="button" data-open-studio>Try the workspace <span>↗</span></button><button id="hero-tour" class="pull-apart-button">Pull it apart <span>+</span></button></div><span class="editorial-concept">A product concept. A working browser demo.</span></section><section class="editorial-copy-block" data-copy="1"><span class="editorial-kicker">01 / LOOK UNDER THE SURFACE</span><h2>Good work<br>has a few<br><em>moving parts.</em></h2><p>Decisions, design, implementation, and evidence. Pull the layers apart to see how they belong together.</p><button class="button" data-open-studio>Step inside <span>↗</span></button></section><section class="editorial-copy-block" data-copy="2"><span class="editorial-kicker">02 / MAKE IT YOURS</span><h2>Change a detail.<br>Follow it<br><em>through.</em></h2><p>Pick a screen. Edit its properties. Inspect the code and compare the result with a checkpoint.</p><button class="button" data-open-studio>Try a real edit <span>↗</span></button></section></div>
  <div class="editorial-art" tabindex="0" role="group" aria-label="Interactive model of the workspace layers" aria-describedby="sculpture-instructions"><div class="art-corner c-tl">+</div><div class="art-corner c-tr">+</div><div class="art-corner c-bl">+</div><div class="art-corner c-br">+</div><div class="sculpture-viewport"><div class="sculpture-stack">
  <div class="paper-plane paper-memory" aria-hidden="true"><div class="paper-chrome"><span>01 / PROJECT MEMORY</span><b>↗</b></div><h3>A decision.<br>With a source.</h3><div class="paper-memory-line"><i></i><span>Use shared design tokens<small>design-system.md / main</small></span></div><div class="paper-memory-line"><i></i><span>Keep the local workflow intact<small>architecture.md / main</small></span></div><div class="paper-memory-line"><i></i><span>Review before accepting<small>quality.md / main</small></span></div><div class="paper-bottom">CONTEXT THAT CARRIES FORWARD <span>⌘</span></div></div>
  <div class="paper-plane paper-design" aria-hidden="true"><div class="paper-chrome"><span>02 / EDITABLE CANVAS</span><b>↗</b></div><div class="paper-design-preview"><span class="paper-mini-mark">✳</span><h3>Your next<br>good idea.</h3><span class="paper-sample-button">Start the project <i>↗</i></span></div><div class="paper-ruler"><span>16</span><i></i><span>24</span><i></i><span>32</span><i></i><span>48</span></div><div class="paper-bottom">INTENT, MADE EDITABLE <span>◈</span></div></div>
  <div class="paper-plane paper-code" aria-hidden="true"><div class="paper-chrome"><span>03 / CONNECTED CODE</span><b>↗</b></div><div class="paper-code-content"><small>src / components / WorkspaceScreen.jsx</small><code><i>export default</i> function Screen() {<br>&nbsp; return (<br>&nbsp;&nbsp; &lt;section style={{<br>&nbsp;&nbsp;&nbsp; gap: <b>16</b>,<br>&nbsp;&nbsp;&nbsp; color: <b>token.accent</b><br>&nbsp;&nbsp; }}&gt;<br>&nbsp;&nbsp;&nbsp; Your next good idea.<br>&nbsp;&nbsp; &lt;/section&gt;<br>&nbsp; );<br>}</code></div><div class="paper-bottom">CHANGES YOU CAN READ <span>⌁</span></div></div>
  <div class="paper-plane paper-evidence" aria-hidden="true"><div class="paper-chrome"><span>04 / VISIBLE EVIDENCE</span><b>↗</b></div><h3>See what<br>checks out.</h3><div class="paper-check"><i>✓</i><span>Meaningful heading</span><b>PASS</b></div><div class="paper-check"><i>✓</i><span>Layout constraints</span><b>PASS</b></div><div class="paper-check"><i>✓</i><span>Design token binding</span><b>PASS</b></div><div class="paper-check"><i>✓</i><span>Text serialization</span><b>PASS</b></div><div class="paper-bottom">ILLUSTRATIVE CHECK REPORT <span>◎</span></div></div>
  </div></div><div class="sculpture-tools"><span id="sculpture-instructions">↔ Drag to rotate <i>/</i> Space to pull apart</span><button id="reset-sculpture" aria-label="Reset the interactive model">Reset ↶</button></div><div class="layer-picker" role="group" aria-label="Bring a workspace layer forward"><button data-paper="0" aria-pressed="false">01 Memory</button><button data-paper="1" aria-pressed="true">02 Design</button><button data-paper="2" aria-pressed="false">03 Code</button><button data-paper="3" aria-pressed="false">04 Checks</button></div><p class="layer-detail" id="layer-detail" aria-live="polite">Editable objects and shared tokens, connected to their implementation.</p></div></div><div class="editorial-story-controls shell"><nav aria-label="Workspace story"><button data-story="0" aria-current="true"><span>01</span> The workspace</button><button data-story="0.43" aria-current="false"><span>02</span> The layers</button><button data-story="0.9" aria-current="false"><span>03</span> The connection</button></nav><button class="scene-pause" aria-label="Pause scene animation" aria-pressed="false">Ⅱ <span>Pause animation</span></button></div><div class="editorial-scroll-line" aria-hidden="true"></div></div>`;
  const replace=(selector,html)=>{const el=document.querySelector(selector);if(el)el.innerHTML=html;};
  replace('.announcement','<span>Blue Nebula — a local-first engineering workspace.</span><button data-resource="vision">Read the product idea ↗</button>');
  replace('#workspace-heading','Start with a screen.<br><span class="muted">Make it your own.</span>');replace('.workspace-section .section-heading>p','Pick a template, edit the details, and inspect the change. Everything in this demo stays in your browser.');
  replace('.connected-section .section-heading h2','Built around<br><span class="muted">the work itself.</span>');replace('.connected-section .section-heading>p','A few things that deserve to stay connected, from the first decision to the final check.');
  replace('.memory-feature h3','Keep the decisions.');replace('.canvas-feature h3','Change the design.');replace('.evidence-feature h3','Review the result.');
  replace('.local-copy h2','Your project.<br><span class="muted">On your terms.</span>');replace('.hardware-copy h3','Choose a starting<br>configuration.');replace('.roadmap-section h2','What comes first.<br><span class="muted">What comes later.</span>');replace('.faq-section h2','A few practical<br><span class="muted">questions.</span>');replace('.closing-content h2','Keep the context.<br><span>Make the next thing.</span>');replace('.closing-content>p','Try the workspace and follow an idea through.');replace('.closing-caption','Start small. Keep going.');
}

export function initEditorialScene(root){
  const art=root.querySelector('.editorial-art'),stack=root.querySelector('.sculpture-stack'),planes=[...root.querySelectorAll('.paper-plane')],copies=[...root.querySelectorAll('[data-copy]')],picker=[...root.querySelectorAll('[data-paper]')],story=[...root.querySelectorAll('[data-story]')];
  const media=matchMedia('(prefers-reduced-motion: reduce)'),compact=matchMedia('(max-width: 760px)');
  let p=0,targetP=0,selected=1,expanded=false,paused=false,blocked=false,visible=true,raf=0,dirty=true,pitch=0,yaw=0,targetPitch=0,targetYaw=0,drag=null,spin=0,lastX=0;
  const captions=['Decisions with their source, scope, and history intact.','Editable objects and shared tokens, connected to their implementation.','Generated files and a readable comparison with your checkpoint.','Named checks, observed results, and reports you can inspect.'];
  function read(){const pin=root.querySelector('.editorial-pin'),r=root.getBoundingClientRect(),top=parseFloat(getComputedStyle(pin).top)||0;targetP=storyProgress(top-r.top,root.offsetHeight-pin.offsetHeight,media.matches||compact.matches);dirty=false;}
  function paint(){
    const state=sculptureLayout(p,expanded,selected),frame=sceneFrame(p),alpha=[frame.intro,frame.chapterOne,frame.chapterTwo];
    const scale=Math.min(1.08,(art.clientWidth-30)/620);stack.style.transform=`translate(-50%,-50%) scale(${scale}) rotateX(${state.pitch+pitch}deg) rotateZ(${state.yaw+yaw}deg)`;
    planes.forEach((plane,i)=>{const s=state.layers[i];plane.style.transform=`translate3d(${s.x}px,${s.y}px,${s.z}px) scale(${s.scale})`;plane.style.opacity=s.opacity;plane.classList.toggle('paper-selected',selected===i);});
    copies.forEach((el,i)=>{el.style.opacity=media.matches?1:alpha[i];el.style.visibility=media.matches||alpha[i]>.02?'visible':'hidden';el.inert=!media.matches&&alpha[i]<.5;el.style.translate=`0 ${(1-alpha[i])*20}px`;});
    const current=p<.2?0:p<.65?1:2;story.forEach((b,i)=>b.setAttribute('aria-current',String(i===current)));root.style.setProperty('--editorial-progress',p);
    const button=root.querySelector('#hero-tour');button.setAttribute('aria-pressed',expanded);button.innerHTML=expanded?'Bring it together <span>−</span>':'Pull it apart <span>+</span>';
  }
  function tick(){raf=0;if(!visible||document.hidden||blocked)return;if(dirty)read();const immediate=paused||media.matches;p=immediate?targetP:p+(targetP-p)*.14;pitch=immediate?targetPitch:pitch+(targetPitch-pitch)*.14;yaw=immediate?targetYaw:yaw+(targetYaw-yaw)*.14;if(!drag&&!immediate&&Math.abs(spin)>.005){targetYaw=Math.max(-65,Math.min(65,targetYaw+spin));spin*=.88;}paint();if(!immediate&&(Math.abs(targetP-p)>.0003||Math.abs(targetPitch-pitch)>.02||Math.abs(targetYaw-yaw)>.02||Math.abs(spin)>.005))raf=requestAnimationFrame(tick);}
  function queue(){if(!raf&&visible&&!document.hidden&&!blocked)raf=requestAnimationFrame(tick);}
  function update(){dirty=true;queue();}
  function toggleExplode(){expanded=!expanded;root.classList.toggle('layers-expanded',expanded);queue();}
  picker.forEach(b=>b.addEventListener('click',()=>{selected=Number(b.dataset.paper);expanded=true;picker.forEach(x=>x.setAttribute('aria-pressed',x===b));root.querySelector('#layer-detail').textContent=captions[selected];queue();}));
  function reset(){targetPitch=targetYaw=0;spin=0;expanded=false;queue();}
  root.querySelector('#reset-sculpture').addEventListener('click',reset);
  art.addEventListener('pointerdown',e=>{if(e.target.closest('button'))return;drag={x:e.clientX,y:e.clientY,pitch:targetPitch,yaw:targetYaw};lastX=e.clientX;spin=0;art.setPointerCapture(e.pointerId);art.classList.add('is-dragging');});
  art.addEventListener('pointermove',e=>{if(!drag)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(e.pointerType==='touch'&&Math.abs(dy)>Math.abs(dx)+8){drag=null;art.classList.remove('is-dragging');if(art.hasPointerCapture(e.pointerId))art.releasePointerCapture(e.pointerId);return;}targetYaw=Math.max(-65,Math.min(65,drag.yaw+dx*.22));targetPitch=Math.max(-30,Math.min(22,drag.pitch-dy*.15));spin=(e.clientX-lastX)*.07;lastX=e.clientX;queue();});
  const release=e=>{drag=null;art.classList.remove('is-dragging');if(art.hasPointerCapture(e.pointerId))art.releasePointerCapture(e.pointerId);queue();};art.addEventListener('pointerup',release);art.addEventListener('pointercancel',release);
  art.addEventListener('keydown',e=>{if(e.target!==art)return;if(e.key==='ArrowLeft')targetYaw-=8;else if(e.key==='ArrowRight')targetYaw+=8;else if(e.key==='ArrowUp')targetPitch-=5;else if(e.key==='ArrowDown')targetPitch+=5;else if(e.key===' '){toggleExplode();e.preventDefault();return;}else if(e.key==='Home'){reset();e.preventDefault();return;}else return;e.preventDefault();targetPitch=Math.max(-30,Math.min(22,targetPitch));targetYaw=Math.max(-65,Math.min(65,targetYaw));queue();});
  story.forEach(b=>b.addEventListener('click',()=>{if(media.matches)return;const top=root.getBoundingClientRect().top+scrollY-(parseFloat(getComputedStyle(root.querySelector('.editorial-pin')).top)||0),distance=root.offsetHeight-root.querySelector('.editorial-pin').offsetHeight;window.scrollTo({top:top+distance*Number(b.dataset.story),behavior:paused?'instant':'smooth'});}));
  window.addEventListener('scroll',update,{passive:true});window.addEventListener('resize',update,{passive:true});new ResizeObserver(update).observe(art);
  new IntersectionObserver(e=>{visible=e[0].isIntersecting;if(!visible&&raf){cancelAnimationFrame(raf);raf=0;}else update();}).observe(root);
  document.addEventListener('visibilitychange',()=>{if(document.hidden&&raf){cancelAnimationFrame(raf);raf=0;}else update();});document.addEventListener('bn:workspace-visibility',e=>{blocked=!!e.detail?.open;if(blocked&&raf){cancelAnimationFrame(raf);raf=0;}else update();});
  media.addEventListener('change',()=>{root.classList.toggle('editorial-reduced',media.matches);update();});root.classList.toggle('editorial-reduced',media.matches);root.classList.add('editorial-ready');update();
  return {toggleExplode,setPaused(value){paused=value;if(value)spin=0;update();}};
}
